# 将子结果映射为后台 Task 结局
段落 运行结局(结果):
  设 原因 为 结果["stopReason"]
  如果 原因 == "completed":
    返回 {"status": "completed", "output": 末段文本(字典获取(结果, "output", []))}
  如果 原因 == "aborted":
    如果 字典包含键(结果, "diagnostic") == 假:
      返回 {"status": "killed"}
    返回 {"status": "failed", "detail": 失败详情(结果)}
  如果 原因 == "error" 或 原因 == "max-tokens" 或 原因 == "refusal":
    返回 {"status": "failed", "detail": 失败详情(结果)}
  返回 {"status": "failed", "detail": 失败详情(结果)}

